raw.command:
Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
$title = 'FSOS-X Cannot Install'
$url = 'www.microsoft.com/software-download/windows11'
if (Test-Path -LiteralPath ($env:windir + '\FSOS')) {
  $global:LASTEXITCODE = 0
  return
}
$detected = $null
$productName = ''
try {
  $pn = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name 'ProductName' -ErrorAction SilentlyContinue).ProductName
  if ($pn) { $productName = [string]$pn }
} catch {}
$editionId = ''
try {
  $ed = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name 'EditionID' -ErrorAction SilentlyContinue).EditionID
  if ($ed) { $editionId = [string]$ed }
} catch {}
$haystack = ($productName + ' ' + $editionId).ToLower()
$oemHaystack = ''
try {
  $oemInfo = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\OEMInformation' -ErrorAction SilentlyContinue
  if ($oemInfo) {
    foreach ($n in @('Manufacturer','Model','SupportURL','SupportPhone','SupportHours','Logo','SupportProvider','SupportAppLink')) {
      $v = $oemInfo.$n
      if ($v) { $oemHaystack += ' ' + ([string]$v) }
    }
  }
} catch {}
$oemHaystack = $oemHaystack.ToLower()
if ($haystack -match '\bfsos\b' -and $haystack -notmatch 'fsos-x') {
  $oldFsosLabel = $productName.Trim()
  if (-not $oldFsosLabel) { $oldFsosLabel = 'a previous FSOS version' }
  $msg = 'FSOS-X cannot be installed over ' + $oldFsosLabel + '. Please reinstall stock Windows first. The latest version can be downloaded from ' + $url
  [System.Windows.Forms.MessageBox]::Show($msg, $title, [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error, [System.Windows.Forms.MessageBoxDefaultButton]::Button1, [System.Windows.Forms.MessageBoxOptions]::DefaultDesktopOnly) | Out-Null
  Stop-Process -Name 'AME Beta','AME Wizard Beta','AME','TrustedUninstaller.CLI' -Force -ErrorAction SilentlyContinue
  $global:LASTEXITCODE = 1
  exit 1
}
$osList = @(
  @{ Name = 'AtlasOS';        Patterns = @('atlasos','atlas os');                  Paths = @('C:\Atlas');          Keys = @('HKLM:\SOFTWARE\AtlasOS') },
  @{ Name = 'ReviOS';         Patterns = @('revios','revi os');                    Paths = @('C:\ReviOS');         Keys = @('HKLM:\SOFTWARE\Revision','HKLM:\SOFTWARE\ReviOS') },
  @{ Name = 'Tiny11';         Patterns = @('tiny11','tiny 11');                    Paths = @('C:\Tiny11');         Keys = @() },
  @{ Name = 'Ghost Spectre';  Patterns = @('ghost spectre','ghostspectre','spectre'); Paths = @('C:\Ghost Spectre'); Keys = @() },
  @{ Name = 'Windows X-Lite'; Patterns = @('x-lite','xlite','windows x lite');     Paths = @('C:\X-Lite');         Keys = @() },
  @{ Name = 'CactusOS';       Patterns = @('cactusos','cactus os');                Paths = @('C:\CactusOS');       Keys = @() },
  @{ Name = 'KernelOS';       Patterns = @('kernelos','kernel os');                Paths = @('C:\KernelOS');       Keys = @() },
  @{ Name = 'YukiOS';         Patterns = @('yukios','yuki os');                    Paths = @('C:\YukiOS');         Keys = @() },
  @{ Name = 'NovaOS';         Patterns = @('novaos','nova os');                    Paths = @('C:\NovaOS');         Keys = @() },
  @{ Name = 'FoxOS';          Patterns = @('foxos','fox os');                      Paths = @('C:\FoxOS');          Keys = @() },
  @{ Name = 'ggOS';           Patterns = @('ggos','gg os');                        Paths = @('C:\ggOS');           Keys = @() },
  @{ Name = 'SapphireOS';     Patterns = @('sapphireos','sapphire os');            Paths = @('C:\SapphireOS');     Keys = @() },
  @{ Name = 'VainOS';         Patterns = @('vainos','vain os');                    Paths = @('C:\VainOS');         Keys = @() },
  @{ Name = 'BlitzOS';        Patterns = @('blitzos','blitz os');                  Paths = @('C:\BlitzOS');        Keys = @() },
  @{ Name = 'AtomOS';         Patterns = @('atomos','atom os');                    Paths = @('C:\AtomOS');         Keys = @() },
  @{ Name = 'IrisOS';         Patterns = @('irisos','iris os');                    Paths = @('C:\IrisOS');         Keys = @() },
  @{ Name = 'PeakOS';         Patterns = @('peakos','peak os');                    Paths = @('C:\PeakOS');         Keys = @() },
  @{ Name = 'xOS';            Patterns = @(' xos ',' x os ');                      Paths = @('C:\xOS');            Keys = @() },
  @{ Name = 'SOS';            Patterns = @(' sos ');                               Paths = @('C:\SOS');            Keys = @() },
  @{ Name = 'WinterOS';       Patterns = @('winteros','winter os');                Paths = @('C:\WinterOS');       Keys = @() },
  @{ Name = 'SynergyOS';      Patterns = @('synergyos','synergy os');              Paths = @('C:\SynergyOS');      Keys = @() },
  @{ Name = 'KirbyOS';        Patterns = @('kirbyos','kirby os');                  Paths = @('C:\KirbyOS');        Keys = @() },
  @{ Name = 'LuminOS';        Patterns = @('luminos','lumin os');                  Paths = @('C:\LuminOS');        Keys = @() }
)
foreach ($os in $osList) {
  if ($detected) { break }
  foreach ($pat in $os.Patterns) {
    if ($haystack.Contains($pat)) { $detected = $os.Name; break }
  }
  if ($detected) { break }
  foreach ($pat in $os.Patterns) {
    if ($oemHaystack -and $oemHaystack.Contains($pat)) { $detected = $os.Name; break }
  }
  if ($detected) { break }
  foreach ($pth in $os.Paths) {
    if (Test-Path -LiteralPath $pth) { $detected = $os.Name; break }
  }
  if ($detected) { break }
  foreach ($k in $os.Keys) {
    if (Test-Path -LiteralPath $k) { $detected = $os.Name; break }
  }
}
if ($detected) {
  $msg = 'FSOS cannot be installed over ' + $detected + '. Supported versions are stock Windows 11 24H2 and 25H2. The latest version can be downloaded from ' + $url
  [System.Windows.Forms.MessageBox]::Show($msg, $title, [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error, [System.Windows.Forms.MessageBoxDefaultButton]::Button1, [System.Windows.Forms.MessageBoxOptions]::DefaultDesktopOnly) | Out-Null
  Stop-Process -Name 'AME Beta','AME Wizard Beta','AME','TrustedUninstaller.CLI' -Force -ErrorAction SilentlyContinue
  $global:LASTEXITCODE = 1
  exit 1
}
$global:LASTEXITCODE = 0

$dest = Join-Path $env:TEMP 'vcredist.exe'
$ok = $false
try {
  $ProgressPreference = 'SilentlyContinue'
  Invoke-WebRequest -Uri 'https://aka.ms/vs/17/release/vc_redist.x64.exe' -OutFile $dest -UseBasicParsing -TimeoutSec 120
  $ok = (Test-Path -LiteralPath $dest) -and ((Get-Item -LiteralPath $dest).Length -gt 0)
} catch { $ok = $false }
if (-not $ok) {
  Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
  $msg = 'FSOS-X requires an active internet connection to download required components (Visual C++ Redistributable). Please connect to the internet and run FSOS-X again.'
  [System.Windows.Forms.MessageBox]::Show($msg, 'FSOS-X Cannot Install', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error, [System.Windows.Forms.MessageBoxDefaultButton]::Button1, [System.Windows.Forms.MessageBoxOptions]::DefaultDesktopOnly) | Out-Null
  Stop-Process -Name 'AME Beta','AME Wizard Beta','AME','TrustedUninstaller.CLI' -Force -ErrorAction SilentlyContinue
  $global:LASTEXITCODE = 1
  exit 1
}
try { Start-Process -FilePath $dest -ArgumentList '/install','/quiet','/norestart' -Wait } catch {}
$global:LASTEXITCODE = 0

$dest = Join-Path $env:TEMP 'FirefoxSetup.exe'
$ok = $false
try {
  $ProgressPreference = 'SilentlyContinue'
  Invoke-WebRequest -Uri 'https://download.mozilla.org/?product=firefox-latest-ssl&os=win64&lang=en-US' -OutFile $dest -UseBasicParsing -TimeoutSec 180
  $ok = (Test-Path -LiteralPath $dest) -and ((Get-Item -LiteralPath $dest).Length -gt 0)
} catch { $ok = $false }
if (-not $ok) {
  Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
  $msg = 'FSOS-X requires an active internet connection to download your selected browser (Firefox). Please connect to the internet and run FSOS-X again.'
  [System.Windows.Forms.MessageBox]::Show($msg, 'FSOS-X Cannot Install', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error, [System.Windows.Forms.MessageBoxDefaultButton]::Button1, [System.Windows.Forms.MessageBoxOptions]::DefaultDesktopOnly) | Out-Null
  Stop-Process -Name 'AME Beta','AME Wizard Beta','AME','TrustedUninstaller.CLI' -Force -ErrorAction SilentlyContinue
  $global:LASTEXITCODE = 1
  exit 1
}
try { Start-Process -FilePath $dest -ArgumentList '/S' -Wait } catch {}
$global:LASTEXITCODE = 0

$target = """$env:ProgramFiles\Mozilla Firefox\firefox.exe"""
$targetX86 = """${env:ProgramFiles(x86)}\Mozilla Firefox\firefox.exe"""
$deadline = (Get-Date).AddMinutes(5)
while ((Get-Date) -lt $deadline) {
  if (Test-Path $target) { break }
  if (Test-Path $targetX86) { $target = $targetX86; break }
  Start-Sleep -Seconds 2
}
if (Test-Path $target) {
  $shell = New-Object -ComObject WScript.Shell
  $sc = $shell.CreateShortcut("""$env:PUBLIC\Desktop\Firefox.lnk""")
  $sc.TargetPath = $target
  $sc.IconLocation = """$target,0"""
  $sc.Save()
}
$global:LASTEXITCODE = 0

$dest = Join-Path $env:TEMP 'BraveSetup.exe'
$ok = $false
try {
  $ProgressPreference = 'SilentlyContinue'
  Invoke-WebRequest -Uri 'https://laptop-updates.brave.com/latest/winx64' -OutFile $dest -UseBasicParsing -TimeoutSec 180
  $ok = (Test-Path -LiteralPath $dest) -and ((Get-Item -LiteralPath $dest).Length -gt 0)
} catch { $ok = $false }
if (-not $ok) {
  Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
  $msg = 'FSOS-X requires an active internet connection to download your selected browser (Brave). Please connect to the internet and run FSOS-X again.'
  [System.Windows.Forms.MessageBox]::Show($msg, 'FSOS-X Cannot Install', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error, [System.Windows.Forms.MessageBoxDefaultButton]::Button1, [System.Windows.Forms.MessageBoxOptions]::DefaultDesktopOnly) | Out-Null
  Stop-Process -Name 'AME Beta','AME Wizard Beta','AME','TrustedUninstaller.CLI' -Force -ErrorAction SilentlyContinue
  $global:LASTEXITCODE = 1
  exit 1
}
try { Start-Process -FilePath $dest -ArgumentList '/silent','/install' -Wait } catch {}
$global:LASTEXITCODE = 0

$dest = Join-Path $env:TEMP 'ChromeSetup.exe'
$ok = $false
try {
  $ProgressPreference = 'SilentlyContinue'
  Invoke-WebRequest -Uri 'https://dl.google.com/chrome/install/latest/chrome_installer.exe' -OutFile $dest -UseBasicParsing -TimeoutSec 180
  $ok = (Test-Path -LiteralPath $dest) -and ((Get-Item -LiteralPath $dest).Length -gt 0)
} catch { $ok = $false }
if (-not $ok) {
  Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
  $msg = 'FSOS-X requires an active internet connection to download your selected browser (Chrome). Please connect to the internet and run FSOS-X again.'
  [System.Windows.Forms.MessageBox]::Show($msg, 'FSOS-X Cannot Install', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error, [System.Windows.Forms.MessageBoxDefaultButton]::Button1, [System.Windows.Forms.MessageBoxOptions]::DefaultDesktopOnly) | Out-Null
  Stop-Process -Name 'AME Beta','AME Wizard Beta','AME','TrustedUninstaller.CLI' -Force -ErrorAction SilentlyContinue
  $global:LASTEXITCODE = 1
  exit 1
}
try { Start-Process -FilePath $dest -ArgumentList '/silent','/install' -Wait } catch {}
$global:LASTEXITCODE = 0

foreach ($activeSetupRoot in @('HKLM:\SOFTWARE\Microsoft\Active Setup\Installed Components','HKLM:\SOFTWARE\Wow6432Node\Microsoft\Active Setup\Installed Components')) {
  if (-not (Test-Path $activeSetupRoot)) { continue }
  Get-ChildItem -Path $activeSetupRoot -ErrorAction SilentlyContinue | ForEach-Object {
    try {
      $name = (Get-ItemProperty -Path $_.PSPath -Name '(default)' -ErrorAction SilentlyContinue).'(default)'
      $stub = (Get-ItemProperty -Path $_.PSPath -Name 'StubPath' -ErrorAction SilentlyContinue).StubPath
      $isVendor = $false
      if ($name -and $name -match 'MicrosoftEdge|Microsoft Edge|Edge Update|OneDrive|GoogleChrome|Google Chrome|Chrome Update|Mozilla|Firefox') { $isVendor = $true }
      if ($stub -and $stub -match 'MicrosoftEdge|msedge|OneDrive|GoogleChrome|chrome\.exe|firefox|Mozilla') { $isVendor = $true }
      if ($isVendor) {
        if ($stub -and $stub.Length -gt 0) {
          try { Set-ItemProperty -Path $_.PSPath -Name 'StubPath' -Value '' -Type ExpandString -Force -ErrorAction SilentlyContinue } catch {}
          try { Remove-ItemProperty -Path $_.PSPath -Name 'StubPath' -Force -ErrorAction SilentlyContinue } catch {}
        }
        if ($name -and $name -match 'Firefox|Mozilla|Google Chrome|Microsoft Edge') {
          try { Remove-Item -Path $_.PSPath -Recurse -Force -ErrorAction SilentlyContinue } catch {}
        }
      }
    } catch {}
  }
}

$eolBase = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\EndOfLife'
if (Test-Path $eolBase) {
  try { Remove-Item -Path $eolBase -Recurse -Force -ErrorAction SilentlyContinue } catch {}
}
$global:LASTEXITCODE = 0

$opts = @()
$optsFile = Join-Path $env:windir 'FSOS\fsos-options.txt'
if (Test-Path $optsFile) { $opts = Get-Content $optsFile -ErrorAction SilentlyContinue }
$unpin = @('Copilot','Microsoft Copilot','Outlook','Outlook (new)','Outlook for Windows','Microsoft Outlook','Dev Home','Phone Link','Microsoft Teams','Teams')
if ($opts -contains 'remove-xbox') { $unpin += @('Xbox','Game Bar','Xbox Game Bar') }
if ($opts -contains 'remove-store') { $unpin += @('Microsoft Store') }
if ($opts -contains 'remove-edge') { $unpin += @('Microsoft Edge','Edge') }
$shell = New-Object -ComObject Shell.Application
$apps = $shell.NameSpace('shell:::{4234d49b-0245-4df3-b780-3893943456e1}')
$apps.Items() | ForEach-Object {
  if ($unpin -contains $_.Name) {
    $_.InvokeVerb('taskbarunpin')
  }
}

$marker = Join-Path $env:windir 'FSOS\.personalization-applied'
if (Test-Path $marker) { $global:LASTEXITCODE = 0; return }
$firstRunOnly = @('SpotifyAB.SpotifyMusic*','*Netflix*','*TikTok*')
foreach ($pat in $firstRunOnly) {
  Get-AppxPackage -AllUsers | Where-Object { $_.Name -like $pat -or $_.PackageFamilyName -like $pat } | ForEach-Object {
    try { Remove-AppxPackage -Package $_.PackageFullName -AllUsers -ErrorAction SilentlyContinue } catch {}
  }
  Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like $pat -or $_.PackageName -like $pat } | ForEach-Object {
    try { Remove-AppxProvisionedPackage -Online -PackageName $_.PackageName -ErrorAction SilentlyContinue | Out-Null } catch {}
  }
}
$global:LASTEXITCODE = 0

try { Stop-Service -Name 'WidgetService' -Force -ErrorAction SilentlyContinue } catch {}
foreach ($n in @('Widgets','WidgetService','widgetservice','msedgewebview2','GameInputSvc')) {
  try { Get-Process -Name $n -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch {}
}
try { taskkill.exe /F /IM 'msedgewebview2.exe' /T 2>$null | Out-Null } catch {}
try { taskkill.exe /F /IM 'Widgets.exe' /T 2>$null | Out-Null } catch {}
try { taskkill.exe /F /IM 'WidgetService.exe' /T 2>$null | Out-Null } catch {}
Start-Sleep -Milliseconds 500
$global:LASTEXITCODE = 0

